    (* [comment removed for export] *)
    P_frame : frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 3400), 3400%Z); (Z_to_bv 64 0x11fd20, 232%Z); (Z_to_bv 64 0x67dbc0, 1%Z)];
    (* [comment removed for export] *)
