    P_wbase : rdn RSEGS mem' (Z_to_bv 64 0x11fd58) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x67dbc0));
    P_write : rdn RSEGS mem' (Z_to_bv 64 0x11fd68) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x104dfc));
    P_buf   : rdn RSEGS mem' (Z_to_bv 64 0x11fd78) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x67dbc0));
    P_bsz   : rdn RSEGS mem' (Z_to_bv 64 0x11fd80) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 1024));
    P_fd    : rdn RSEGS mem' (Z_to_bv 64 0x11fd98) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 1));
    P_mode  : rdn RSEGS mem' (Z_to_bv 64 0x11fda8) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
    P_lock  : rdn RSEGS mem' (Z_to_bv 64 0x11fdac) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
    P_lbf   : rdn RSEGS mem' (Z_to_bv 64 0x11fdb0) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
    P_can   : rdn RSEGS mem' (Z_to_bv 64 0x67d4f0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
    P_stk   : stk_ok RSEGS mem' sp 3400 }.

  Definition p1_vals (regs : bvmap 5 word) (sp : word) (can : Z) : list word :=
    [sp; Z_to_bv 64 can] ++ junk_vals regs.

